CREATE OR REPLACE FUNCTION public.cleanup_expired_phone_verifications()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    cleaned_count INTEGER;
BEGIN
    -- Update expired verification codes in users table
    UPDATE users 
    SET 
        phone_verification_code = NULL,
        phone_verification_expires_at = NULL
    WHERE phone_verification_expires_at IS NOT NULL 
        AND phone_verification_expires_at < NOW();
    
    GET DIAGNOSTICS cleaned_count = ROW_COUNT;
    
    -- Update expired verification logs
    UPDATE phone_verification_logs 
    SET status = 'expired'
    WHERE status = 'sent' 
        AND expires_at < NOW();
    
    RETURN cleaned_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.copy_coordinates_to_permit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Copy coordinates from the associated application (any valid geometry type)
    UPDATE public.permits 
    SET coordinates = (
        SELECT coordinates 
        FROM public.applications 
        WHERE id = NEW.application_id
        AND coordinates IS NOT NULL
        AND ST_IsValid(coordinates)
    )
    WHERE id = NEW.id;
    
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_email_verification_code(p_email text, p_purpose text DEFAULT 'signup'::text, p_ttl_minutes integer DEFAULT 15)
 RETURNS TABLE(out_id uuid, out_email text, out_code text, out_purpose text, out_expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_code TEXT;
BEGIN
  -- Invalidate prior active codes for same email/purpose
  UPDATE public.email_verification_codes evc
     SET consumed_at = NOW(), updated_at = NOW()
   WHERE evc.email = LOWER(p_email)
     AND evc.purpose = p_purpose
     AND evc.consumed_at IS NULL;

  -- Generate 6-digit code
  v_code := LPAD((FLOOR(RANDOM() * 1000000))::INT::TEXT, 6, '0');

  -- Return the inserted row
  RETURN QUERY
  INSERT INTO public.email_verification_codes(email, code, purpose, expires_at)
  VALUES (LOWER(p_email), v_code, p_purpose, NOW() + MAKE_INTERVAL(mins => p_ttl_minutes))
  RETURNING public.email_verification_codes.id,
            public.email_verification_codes.email,
            public.email_verification_codes.code,
            public.email_verification_codes.purpose,
            public.email_verification_codes.expires_at;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_polygon_from_coordinates(coord_array jsonb)
 RETURNS geometry
 LANGUAGE plpgsql
AS $function$
DECLARE
    wkt_string TEXT;
    coord_item JSONB;
    lat FLOAT;
    lng FLOAT;
    point_count INTEGER := 0;
    points_array TEXT[] := '{}';
BEGIN
    -- Validate input
    IF coord_array IS NULL OR jsonb_array_length(coord_array) = 0 THEN
        RETURN NULL;
    END IF;
    
    -- Build array of coordinate pairs
    FOR coord_item IN SELECT value FROM jsonb_array_elements(coord_array)
    LOOP
        -- Extract and validate lat/lng
        lat := (coord_item->>'latitude')::FLOAT;
        lng := (coord_item->>'longitude')::FLOAT;
        
        -- Skip invalid coordinates
        IF lat IS NULL OR lng IS NULL OR 
           lat < -90 OR lat > 90 OR 
           lng < -180 OR lng > 180 THEN
            CONTINUE;
        END IF;
        
        -- Add point to array (PostGIS uses lng lat order)
        points_array := array_append(points_array, lng::TEXT || ' ' || lat::TEXT);
        point_count := point_count + 1;
    END LOOP;
    
    -- Need exactly 5 points for our polygon requirement
    IF point_count != 5 THEN
        RETURN NULL;
    END IF;
    
    -- Close the polygon by adding the first point at the end
    points_array := array_append(points_array, points_array[1]);
    
    -- Build WKT string
    wkt_string := 'POLYGON((' || array_to_string(points_array, ',') || '))';
    
    -- Return as PostGIS geometry with SRID 4326 (WGS84)
    RETURN ST_GeomFromText(wkt_string, 4326);
    
EXCEPTION WHEN OTHERS THEN
    -- Return NULL on any error
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_inspection_review_only_update()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  is_reviewer BOOLEAN;
  old_clean JSONB;
  new_clean JSONB;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.users
    WHERE public.users.id = auth.uid()
      AND public.users.role IN ('reviewer', 'admin', 'approver')
  ) INTO is_reviewer;

  IF NOT is_reviewer THEN
    RETURN NEW;
  END IF;

  old_clean := to_jsonb(OLD)
    - 'review_status'
    - 'review_notes'
    - 'reviewed_by'
    - 'reviewed_at'
    - 'updated_at';

  new_clean := to_jsonb(NEW)
    - 'review_status'
    - 'review_notes'
    - 'reviewed_by'
    - 'reviewed_at'
    - 'updated_at';

  IF new_clean IS DISTINCT FROM old_clean THEN
    RAISE EXCEPTION 'Reviewers may only update review fields (review_status, review_notes, reviewed_by, reviewed_at).';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_ended_delegations()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE role_delegations
    SET status = 'expired',
        updated_at = NOW()
    WHERE status = 'active'
      AND end_date IS NOT NULL
      AND end_date < NOW();
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_old_applications()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  updated_count integer := 0;
BEGIN
  WITH updated AS (
    UPDATE applications a
    SET status = 'expired',
        updated_at = NOW()
    WHERE
      a.submitted_at IS NOT NULL
      AND COALESCE(a.expires_at, a.submitted_at + INTERVAL '6 months') <= NOW()
      AND a.status NOT IN ('approved', 'rejected', 'cancelled', 'expired')
      AND NOT EXISTS (
        SELECT 1 FROM permits p WHERE p.application_id = a.id
      )
    RETURNING 1
  )
  SELECT COUNT(*) INTO updated_count FROM updated;

  RETURN updated_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_application_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    year_prefix VARCHAR(4);
    counter INTEGER;
    new_number VARCHAR(50);
BEGIN
    IF NEW.application_number IS NULL THEN
        year_prefix := EXTRACT(YEAR FROM NOW())::VARCHAR;
        
        -- Fixed: Extract from position 10 to get just the numeric part
        -- For "RWB-2025-000001", this extracts "000001"
        SELECT COALESCE(MAX(CAST(SUBSTRING(application_number FROM 10) AS INTEGER)), 0) + 1
        INTO counter
        FROM applications
        WHERE application_number LIKE 'RWB-' || year_prefix || '-%';
        
        new_number := 'RWB-' || year_prefix || '-' || LPAD(counter::VARCHAR, 6, '0');
        NEW.application_number := new_number;
        
        -- Debug logging (optional - can be removed in production)
        RAISE NOTICE 'Generated application number: %, Counter: %', new_number, counter;
    END IF;
    
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_assessment_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  year_suffix TEXT;
  seq_val BIGINT;
BEGIN
  IF NEW.assessment_number IS NOT NULL THEN
    RETURN NEW;
  END IF;

  year_suffix := TO_CHAR(CURRENT_DATE, 'YY');
  seq_val := NEXTVAL('assessment_number_seq');
  NEW.assessment_number := 'TA-' || year_suffix || '-' || LPAD(seq_val::TEXT, 6, '0');
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_permit_number()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    year_prefix VARCHAR(4);
    counter INTEGER;
    new_number VARCHAR(50);
BEGIN
    IF NEW.permit_number IS NULL THEN
        year_prefix := EXTRACT(YEAR FROM NOW())::VARCHAR;
        
        -- Find the max counter for the current year with the new format
        SELECT COALESCE(MAX(CAST(SUBSTRING(permit_number FROM 1 FOR 6) AS INTEGER)), 0) + 1
        INTO counter
        FROM permits
        WHERE permit_number LIKE '%' || '/RWB/' || year_prefix;
        
        new_number := LPAD(counter::VARCHAR, 6, '0') || '/RWB/' || year_prefix;
        NEW.permit_number := new_number;
    END IF;
    
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_verification_code()
 RETURNS character varying
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN LPAD(FLOOR(RANDOM() * 1000000)::TEXT, 6, '0');
END;
$function$

CREATE OR REPLACE FUNCTION public.get_active_delegations_for_user(user_uuid uuid)
 RETURNS TABLE(delegation_id uuid, delegator_id uuid, delegated_role delegatable_role, start_date timestamp with time zone, end_date timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- First, expire any ended delegations
    PERFORM expire_ended_delegations();
    
    RETURN QUERY
    SELECT 
        rd.id as delegation_id,
        rd.delegator_id,
        rd.delegated_role,
        rd.start_date,
        rd.end_date
    FROM role_delegations rd
    WHERE rd.delegate_id = user_uuid
      AND rd.status = 'active'
      AND rd.start_date <= NOW()
      AND (rd.end_date IS NULL OR rd.end_date > NOW());
END;
$function$

CREATE OR REPLACE FUNCTION public.get_approved_permit_polygons()
 RETURNS TABLE(permit_id uuid, permit_number character varying, project_title character varying, coordinates_geojson jsonb, status permit_status, issued_date date, expiry_date date)
 LANGUAGE plpgsql
AS $function$
BEGIN
    RETURN QUERY
    SELECT 
        p.id,
        p.permit_number,
        a.project_title,
        ST_AsGeoJSON(p.coordinates)::JSONB as coordinates_geojson,
        p.status,
        p.issued_date,
        p.expiry_date
    FROM public.permits p
    JOIN public.applications a ON p.application_id = a.id
    WHERE p.coordinates IS NOT NULL
    AND ST_IsValid(p.coordinates)
    ORDER BY p.issued_date DESC;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    existing_user UUID;
BEGIN
    -- Check if user already exists
    SELECT id INTO existing_user FROM public.users WHERE id = NEW.id LIMIT 1;
    
    IF existing_user IS NOT NULL THEN
        RETURN NEW;
    END IF;
    
    -- Insert new user
    BEGIN
        INSERT INTO public.users (
            id, 
            email, 
            role, 
            status, 
            account_type,
            first_name,
            last_name,
            company_name,
            company_tin, 
            company_address,
            company_phone,
            applications_count, 
            reviews_count, 
            inspections_count,
            profile_completed,
            created_at, 
            updated_at
        ) VALUES (
            NEW.id, 
            NEW.email, 
            'applicant', 
            'active', 
            'individual',
            'User',
            'Profile',
            NULL,
            NULL,
            NULL,
            NULL,
            0, 
            0, 
            0,
            FALSE,
            NOW(), 
            NOW()
        );
    EXCEPTION
        WHEN unique_violation THEN
            NULL;
        WHEN OTHERS THEN
            RAISE LOG 'handle_new_user error: %', SQLERRM;
    END;
    
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.has_active_delegation(user_uuid uuid, check_role delegatable_role)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
    has_delegation BOOLEAN;
BEGIN
    -- First, expire any ended delegations
    PERFORM expire_ended_delegations();
    
    SELECT EXISTS (
        SELECT 1
        FROM role_delegations rd
        WHERE rd.delegate_id = user_uuid
          AND rd.delegated_role = check_role
          AND rd.status = 'active'
          AND rd.start_date <= NOW()
          AND (rd.end_date IS NULL OR rd.end_date > NOW())
    ) INTO has_delegation;
    
    RETURN has_delegation;
END;
$function$

CREATE OR REPLACE FUNCTION public.increment_quarterly_permits()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
    current_year INTEGER;
    current_quarter INTEGER;
    quarter_string VARCHAR(7);
BEGIN
    current_year := EXTRACT(year FROM NOW())::INTEGER;
    current_quarter := EXTRACT(quarter FROM NOW())::INTEGER;
    quarter_string := current_year || '-Q' || current_quarter;
    
    INSERT INTO quarterly_permit_stats (year, quarter_num, quarter, permits_issued)
    VALUES (
        current_year, 
        current_quarter,
        quarter_string,
        1
    )
    ON CONFLICT (year, quarter_num) 
    DO UPDATE SET 
        permits_issued = quarterly_permit_stats.permits_issued + 1,
        updated_at = NOW();
END;
$function$

CREATE OR REPLACE FUNCTION public.log_application_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF (TG_OP = 'UPDATE') AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    INSERT INTO public.workflow_history (
      application_id,
      user_id,
      from_status,
      to_status,
      action,
      comment,
      created_at
    ) VALUES (
      NEW.id,
      auth.uid(),  -- May be NULL for service role operations
      OLD.status::text,
      NEW.status::text,
      'status_change',
      NULL,
      NOW()
    );
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_email_verification_attempt(user_uuid uuid, user_email text, verification_type text DEFAULT 'signup'::text, user_ip inet DEFAULT NULL::inet, user_agent_string text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    log_id UUID;
BEGIN
    INSERT INTO email_verification_logs (
        user_id,
        email,
        verification_type,
        token_sent,
        sent_at,
        ip_address,
