   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['approver'::user_role, 'admin'::user_role]))))))) with check (((auth.uid() = approver_id) AND (EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['approver'::user_role, 'admin'::user_role])))))));
create policy "Approvers can update their own comment approvals" on public.approvals as permissive for UPDATE to public using (((auth.uid() = approver_id) AND ((decision)::text = 'comment'::text))) with check (((auth.uid() = approver_id) AND ((decision)::text = 'comment'::text)));
