  WHERE ((applications.id = inspections.application_id) AND (applications.applicant_id = auth.uid())))));
create policy "Authenticated users can insert own inspections" on public.inspections as permissive for INSERT to public with check (((auth.uid() IS NOT NULL) AND (auth.uid() = inspector_id)));
create policy "Authenticated users can view inspections" on public.inspections as permissive for SELECT to public using ((auth.uid() IS NOT NULL));
create policy "Inspectors can update their own inspections" on public.inspections as permissive for UPDATE to public using (((auth.uid() = inspector_id) AND ((lower(COALESCE(((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text), ((auth.jwt() -> 'user_metadata'::text) ->> 'role'::text), ''::text)) = ANY (ARRAY['assessor'::text, 'inspector'::text, 'admin'::text])) OR (lower(COALESCE(( SELECT (users.role)::text AS role
   FROM users
  WHERE (users.id = auth.uid())), ''::text)) = ANY (ARRAY['assessor'::text, 'inspector'::text, 'admin'::text])) OR (EXISTS ( SELECT 1
   FROM applications a
  WHERE ((a.id = inspections.application_id) AND (((to_jsonb(a.*) ->> 'assigned_inspector_id'::text))::uuid = auth.uid()))))))) with check (((auth.uid() = inspector_id) AND ((lower(COALESCE(((auth.jwt() -> 'app_metadata'::text) ->> 'role'::text), ((auth.jwt() -> 'user_metadata'::text) ->> 'role'::text), ''::text)) = ANY (ARRAY['assessor'::text, 'inspector'::text, 'admin'::text])) OR (lower(COALESCE(( SELECT (users.role)::text AS role
   FROM users
  WHERE (users.id = auth.uid())), ''::text)) = ANY (ARRAY['assessor'::text, 'inspector'::text, 'admin'::text])) OR (EXISTS ( SELECT 1
   FROM applications a
  WHERE ((a.id = inspections.application_id) AND (((to_jsonb(a.*) ->> 'assigned_inspector_id'::text))::uuid = auth.uid())))))));
create policy "Users can update own inspections" on public.inspections as permissive for UPDATE to public using ((auth.uid() = inspector_id)) with check ((auth.uid() = inspector_id));
create policy "Users can view inspections for their applications" on public.inspections as permissive for SELECT to public using ((EXISTS ( SELECT 1
   FROM applications a
  WHERE ((a.id = inspections.application_id) AND (a.applicant_id = auth.uid())))));
