   FROM users u
  WHERE ((u.id = auth.uid()) AND (u.role = ANY (ARRAY['admin'::user_role, 'approver'::user_role, 'reviewer'::user_role, 'inspector'::user_role, 'assessor'::user_role, 'verifier'::user_role]))))));
