create policy "Allow public read for active permits by number" on public.permits as permissive for SELECT to public using ((status = 'active'::permit_status));
create policy "Staff can create permits for approved applications" on public.permits as permissive for INSERT to public with check (((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['reviewer'::user_role, 'inspector'::user_role, 'admin'::user_role, 'approver'::user_role]))))) OR (EXISTS ( SELECT 1
   FROM applications
  WHERE ((applications.id = permits.application_id) AND (applications.applicant_id = auth.uid()) AND (applications.status = 'approved_pending_permit'::application_status))))));
create policy "Staff can update permits" on public.permits as permissive for UPDATE to public using (((EXISTS ( SELECT 1
   FROM users
  WHERE ((users.id = auth.uid()) AND (users.role = ANY (ARRAY['admin'::user_role, 'approver'::user_role]))))) OR ((EXISTS ( SELECT 1
   FROM applications orig_app
  WHERE ((orig_app.id = permits.application_id) AND (orig_app.applicant_id = auth.uid())))) AND (EXISTS ( SELECT 1
   FROM applications mod_app
  WHERE ((mod_app.applicant_id = auth.uid()) AND (mod_app.status = 'approved_pending_permit'::application_status) AND ((mod_app.is_modification = true) OR (mod_app.is_renewal = true))))))));
